#!/usr/bin/env python3
"""Apply the Galaxy A51 (SM-A515F, Exynos 9611) hardware layer to an
A5XELTE-patched xnu tree (tools/dreamlte/prep-xnu-tree.sh output).

Two routes to the same result, both driven by tools/a51/a51_board.py:
  * this script, for a working tree with no git: it runs the proven dreamlte
    layer first (that is what turns every hard-coded A5XELTE constant into an
    A5_* macro and brings in the Exynos UFS quirks), then applies the A51 board
    transform;
  * xnu/patches/0125-a51-exynos9611.patch, generated by tools/a51/mkpatch0125.py
    for the patch pipeline / CI.
tools/a51/verify-board-routes.sh proves the two agree byte for byte on a real
xnu-8796.141.3 tree.

All board values are measured on hardware by shim/a51 and recorded in
A51_PROGRESS.md; a51_board.py carries the per-value provenance.

Usage: apply-a51.py XNU_TREE [--skip-stage1]
"""
import subprocess
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))
import a51_board as B

DREAMLTE_APPLY = HERE.parent / 'dreamlte' / 'apply-dreamlte.py'

tree = Path(sys.argv[1]).resolve()
skip_stage1 = '--skip-stage1' in sys.argv

hdr = tree / B.HEADER_REL
if not hdr.exists():
    raise SystemExit(f'{tree} is not an A5XELTE-patched xnu tree '
                     f'({B.HEADER_REL} missing); run '
                     'tools/dreamlte/prep-xnu-tree.sh first')

if not skip_stage1:
    print(f'== stage 1: {DREAMLTE_APPLY.name} on {tree}')
    subprocess.run([sys.executable, str(DREAMLTE_APPLY), str(tree)], check=True)

print('== stage 2: A51 board layer')
for rel in B.EDITED_FILES:
    path = tree / rel
    if not path.exists():
        print(f'  WARNING: {rel} not present, skipped')
        continue
    before = path.read_text()
    after = B.transformed_file(rel, before)
    if after == before:
        print(f'  unchanged {rel}')
        continue
    path.write_text(after)
    added = len(after.splitlines()) - len(before.splitlines())
    print(f'  edited    {rel} ({added:+d} lines)')

print('\nA51 board facts now in the tree:')
for line in B.A51_HEADER_BLOCK:
    if line.startswith('#define') or line.startswith('#undef'):
        print('  ' + line)
print('\nDREAMLTE guards extended for A51:')
for rel, occ, _ in B.GUARD_SITES:
    print(f'  {rel}: occurrence {occ}')
print('\nA5XELTE (S8 config) branches split for A51:')
for rel, occ, _ in B.A5XELTE_GUARD_SITES:
    print(f'  {rel}: occurrence {occ}')
